/**
 * Host-side Git on a worktree the sandboxed agent can write to. The agent can rewrite the worktree's `.git` pointer (or
 * plant a nested repository); Git would then read the planted repository's configuration on the host, where a
 * `filter.*.clean` or `gpg.program` setting is a command. Every host-side call must refuse such a worktree first.
 * Also: merge races that another terminal can win between the checks and the mutation.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { runWorktreeCommand } from "../src/worktrunk/command.js";
import { mergeSeams } from "../src/worktrunk/merge.js";

function git(cwd: string, ...args: string[]): string {
  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

function fixture(name = "feat/t") {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-wttrust-")));
  const repo = path.join(root, "proj");
  const home = path.join(root, "home");
  fs.mkdirSync(repo);
  fs.mkdirSync(home);
  git(repo, "init", "-q", "-b", "main");
  git(repo, "config", "user.email", "t@example.com");
  git(repo, "config", "user.name", "T");
  git(repo, "config", "commit.gpgsign", "false");
  fs.writeFileSync(path.join(repo, ".gitignore"), "ignored.log\n");
  fs.writeFileSync(path.join(repo, "a.txt"), "one\n");
  git(repo, "add", ".");
  git(repo, "commit", "-q", "-m", "init");
  const made = runWorktreeCommand(["switch", "-c", name, "--no-copy"], { cwd: repo, home, readOnly: false });
  assert.equal(made.success, true, made.output);
  const dir = path.join(repo, ".nexus", "worktrees", name.replace("/", "-"));
  return { root, repo, home, dir, merge: (extra: string[] = []) => runWorktreeCommand(["merge", "--no-verify-receipt", "--reason", "trust fixture", ...extra], { cwd: dir, home, readOnly: false }), cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

/** Rewrites the worktree's `.git` pointer to a repository planted INSIDE the worktree whose config runs `marker`-writing commands. */
function plantRepository(f: ReturnType<typeof fixture>, branch: string, config: string[]): string {
  const marker = path.join(f.root, "MARKER");
  const plant = path.join(f.dir, "plant");
  fs.mkdirSync(plant);
  git(plant, "init", "-q", "-b", "main");
  git(plant, "config", "user.email", "t@example.com");
  git(plant, "config", "user.name", "T");
  fs.writeFileSync(path.join(plant, "seed"), "seed\n");
  git(plant, "add", "seed");
  git(plant, "-c", "commit.gpgsign=false", "commit", "-q", "-m", "seed");
  git(plant, "branch", branch);
  git(plant, "worktree", "add", "-q", "-b", `${branch}-wt`, path.join(f.root, "planted-wt"));
  const admin = path.join(plant, ".git", "worktrees", "planted-wt");
  fs.writeFileSync(path.join(admin, "gitdir"), path.join(f.dir, ".git") + "\n");
  fs.writeFileSync(path.join(admin, "HEAD"), `ref: refs/heads/${branch}\n`);
  for (const line of config) git(plant, "config", ...line.replace("@MARKER@", marker).split("\u0000"));
  fs.writeFileSync(path.join(f.dir, ".git"), `gitdir: ${admin}\n`);
  fs.writeFileSync(path.join(f.dir, ".gitattributes"), "* filter=plant\n");
  fs.writeFileSync(path.join(f.dir, "a.txt"), "edited by the agent\n");
  return marker;
}

test("a worktree whose .git pointer leads into a repository planted inside it is refused before any filter or program runs", () => {
  const f = fixture();
  try {
    const marker = plantRepository(f, "feat/t", [
      `filter.plant.clean\u0000sh -c 'echo ran > @MARKER@; cat'`,
      `commit.gpgsign\u0000true`,
      `gpg.program\u0000sh -c 'echo gpg > @MARKER@'`,
    ]);
    const r = f.merge();
    assert.equal(fs.existsSync(marker), false, `a planted configuration command ran on the host: ${r.output}`);
    assert.equal(r.success, false, r.output);
    assert.match(r.output, /not a trusted worktree/i);
  } finally { f.cleanup(); }
});

test("a clean multi-commit source: content force-added after the snapshot refuses the merge and keeps the worktree", () => {
  const f = fixture("feat/two");
  try {
    for (const n of ["x", "y"]) { fs.writeFileSync(path.join(f.dir, n), n); git(f.dir, "add", n); git(f.dir, "commit", "-q", "-m", n); }
    mergeSeams.preMerge = () => { fs.writeFileSync(path.join(f.dir, "ignored.log"), "staged on purpose\n"); git(f.dir, "add", "-f", "ignored.log"); };
    let r;
    try { r = f.merge(); } finally { delete mergeSeams.preMerge; }
    assert.equal(r.success, false, r.output);
    assert.match(r.output, /index changed|staged/i);
    assert.equal(fs.existsSync(path.join(f.dir, "ignored.log")), true, "the worktree and the file are kept");
    assert.equal(git(f.repo, "ls-tree", "-r", "--name-only", "HEAD").split("\n").includes("x"), false, "nothing was merged");
  } finally { f.cleanup(); }
});

test("a target checkout switched to another branch at the same commit is refused, not fast-forwarded under main's name", () => {
  const f = fixture("feat/tgt");
  try {
    fs.writeFileSync(path.join(f.dir, "w.txt"), "w\n");
    git(f.dir, "add", "w.txt");
    git(f.dir, "commit", "-q", "-m", "work");
    mergeSeams.preMerge = () => git(f.repo, "switch", "-q", "-c", "other"); // same commit as main
    let r;
    try { r = f.merge(); } finally { delete mergeSeams.preMerge; }
    assert.equal(r.success, false, r.output);
    assert.match(r.output, /target|switched|main/i);
    assert.equal(git(f.repo, "rev-parse", "other"), git(f.repo, "rev-parse", "main"), "the switched-to branch was not advanced");
    assert.equal(git(f.repo, "ls-tree", "-r", "--name-only", "HEAD").includes("w.txt"), false);
  } finally { f.cleanup(); }
});

test("trust table: legitimate layouts pass, planted ones are refused", async () => {
  const { untrustedCheckoutReason } = await import("../src/worktrunk/git.js");
  const f = fixture("feat/table");
  try {
    assert.equal(untrustedCheckoutReason(f.repo), undefined, "the main checkout");
    assert.equal(untrustedCheckoutReason(f.dir), undefined, "a linked worktree");
    fs.mkdirSync(path.join(f.dir, "sub", "deeper"), { recursive: true });
    assert.equal(untrustedCheckoutReason(path.join(f.dir, "sub", "deeper")), undefined, "a subdirectory of a linked worktree");
    assert.equal(untrustedCheckoutReason(path.join(f.root, "not-a-repo-at-all")), undefined, "a path that does not exist");
    // a repository (with its own configuration) planted as a directory inside the worktree
    git(path.join(f.dir, "sub"), "init", "-q");
    assert.match(String(untrustedCheckoutReason(path.join(f.dir, "sub"))), /nested inside the linked worktree/);
    fs.rmSync(path.join(f.dir, "sub", ".git"), { recursive: true });
    // a pointer to a directory inside the worktree, to another worktree's admin directory, and a symlinked .git
    fs.mkdirSync(path.join(f.dir, "fake", "worktrees", "w"), { recursive: true });
    fs.writeFileSync(path.join(f.dir, "sub", ".git"), `gitdir: ${path.join(f.dir, "fake", "worktrees", "w")}\n`);
    assert.match(String(untrustedCheckoutReason(path.join(f.dir, "sub"))), /inside the worktree itself/);
    fs.rmSync(path.join(f.dir, "sub", ".git"));
    fs.symlinkSync(path.join(f.repo, ".git"), path.join(f.dir, "sub", ".git"));
    assert.match(String(untrustedCheckoutReason(path.join(f.dir, "sub"))), /nested|plain pointer/);
  } finally { f.cleanup(); }
});
/**
 * The one place the worktree feature runs Git.
 *
 * Every call pins the configuration that could otherwise turn a repository into code execution or change what a
 * result means: no replace objects, no hooks (`core.hooksPath` plus the Git 2.54+ configured-hook switch), no
 * fsmonitor, no external transport helpers, no inherited repository-selecting environment. Refs and paths that
 * come from a user are passed after `--end-of-options`; callers also validate them first (see paths.ts), so a
 * name such as `--upload-pack=...` is refused before it reaches Git.
 *
 * Trust boundary: `.git/config`, the user's and the system's Git configuration are trusted as Git trusts them. Hooks,
 * fsmonitor and external transports are pinned off because a checkout can reach them, but a `filter.<name>.clean`
 * command configured in that trusted configuration still runs when `git status` compares content; `.gitattributes`
 * can only name a filter, never define its command.
 */
import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import { envWithoutConfiguredHooks } from "../core/git_hook_guard.js";
import { PATHSPEC_MODE_ENV } from "../git.js";
import { redactSecrets } from "../ui.js";

/** Hook events Nexus-initiated worktree commands must never fire. */
export const SUPPRESSED_HOOK_EVENTS = [
  "post-checkout", "pre-commit", "prepare-commit-msg", "commit-msg", "post-commit", "post-merge",
  "pre-merge-commit", "pre-rebase", "post-rewrite", "reference-transaction", "post-index-change", "pre-auto-gc",
] as const;

export const PINNED_GIT_FLAGS: readonly string[] = [
  "--no-replace-objects",
  "--no-optional-locks",
  "-c", "core.hooksPath=/dev/null",
  "-c", "core.fsmonitor=false",
  "-c", "protocol.ext.allow=never",
  "-c", "submodule.recurse=false",
  "-c", "core.quotePath=false",
];

/** Variables that would redirect Git at another repository, object store, diff driver or ref namespace, or change how pathspecs are read. */
export const SCRUBBED_ENV = [
  "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
  "GIT_COMMON_DIR", "GIT_NAMESPACE", "GIT_EXTERNAL_DIFF", "GIT_REPLACE_REF_BASE", "GIT_PAGER", "GIT_SSH_COMMAND",
  "GIT_ASKPASS", "GIT_EDITOR", "GIT_SEQUENCE_EDITOR", "GIT_PREFIX", "GIT_CEILING_DIRECTORIES",
  ...PATHSPEC_MODE_ENV,
];

export class GitError extends Error {
  constructor(message: string, readonly status: number | null, readonly args: readonly string[]) {
    super(message);
    this.name = "GitError";
  }
}

export interface GitResult { status: number | null; stdout: string; stderr: string; timedOut: boolean }

export interface GitOptions {
  /** Milliseconds before the child is killed (default 30 s). */
  timeoutMs?: number;
  /** Do not throw on a non-zero exit. */
  allowFailure?: boolean;
  /** Extra environment (applied after scrubbing); never the repository selectors. */
  env?: Record<string, string>;
  maxBuffer?: number;
  /** Text for the child's standard input (for `--stdin` forms). */
  input?: string;
}

function inside(root: string, candidate: string): boolean {
  return candidate === root || candidate.startsWith(root + path.sep);
}

/**
 * The agent runs in a sandbox that can write its worktree, `.git` pointer included, but nothing outside it. Git reads
 * the configuration of whatever repository `.git` leads to; a planted one can carry commands (`filter.*.clean`,
 * `commit.gpgsign` with `gpg.program`) that would run on the host. A linked worktree is therefore trusted only when its
 * `.git` file leads to an administrative directory that is OUTSIDE the worktree (so outside what the agent could write),
 * sits under `<common>/worktrees/`, and points back at this very `.git` file; and a repository nested inside a linked
 * worktree is never trusted. Returns the reason, or undefined when `cwd` is fine (or not in a repository at all).
 */
export function untrustedCheckoutReason(cwd: string): string | undefined {
  let start: string;
  try { start = fs.realpathSync(cwd); } catch { return undefined; }
  // Every `.git` on the way up from `cwd`. The outermost `.git` FILE is the boundary the sandboxed agent can write.
  const files: string[] = [];
  const directories: string[] = [];
  for (let dir = start; ; dir = path.dirname(dir)) {
    try {
      if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
    } catch { /* no .git here */ }
    if (path.dirname(dir) === dir) break;
  }
  const outer = files[files.length - 1];
  if (!outer) return undefined; // a plain repository (or none): not a sandbox-writable checkout
  // A repository with a real `.git` directory below that boundary was planted (or cloned) inside the writable area.
  const planted = directories.find((dir) => inside(outer, dir));
  if (planted) return `${planted} is a repository nested inside the linked worktree ${outer}`;
  for (const root of files) {
    const dotGit = path.join(root, ".git");
    try {
      const stat = fs.lstatSync(dotGit);
      if (stat.isSymbolicLink() || !stat.isFile() || stat.size > 4096) return `${dotGit} is not a plain pointer file`;
      const match = /^gitdir: (.+)$/m.exec(fs.readFileSync(dotGit, "utf8"));
      if (!match) return `${dotGit} is not a gitdir pointer`;
      const admin = fs.realpathSync(path.resolve(root, match[1].trim()));
      if (inside(outer, admin)) return `${dotGit} leads into a repository inside the worktree itself`;
      if (path.basename(path.dirname(admin)) === "worktrees") {
        const common = fs.realpathSync(path.dirname(path.dirname(admin)));
        if (inside(outer, common)) return `${dotGit} leads into a repository inside the worktree itself`;
        const back = fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim();
        if (fs.realpathSync(path.resolve(admin, back)) !== path.join(root, ".git")) return `the administrative directory behind ${dotGit} does not point back at it`;
      }
    } catch {
      return `${dotGit} could not be verified`;
    }
  }
  return undefined;
}

let hookEnvCache: { key: string; env: NodeJS.ProcessEnv } | undefined;

function baseEnv(): NodeJS.ProcessEnv {
  // Computed per process-environment value: envWithoutConfiguredHooks spawns `git --version`.
  const key = process.env.GIT_CONFIG_PARAMETERS ?? "";
  if (!hookEnvCache || hookEnvCache.key !== key) {
    hookEnvCache = { key, env: envWithoutConfiguredHooks(process.cwd(), SUPPRESSED_HOOK_EVENTS) };
  }
  const env: NodeJS.ProcessEnv = { ...hookEnvCache.env };
  for (const name of SCRUBBED_ENV) delete env[name];
  env.GIT_TERMINAL_PROMPT = "0";
  env.LC_ALL = "C";
  env.LANGUAGE = "C";
  return env;
}

export function git(cwd: string, args: readonly string[], options: GitOptions = {}): GitResult {
  const untrusted = untrustedCheckoutReason(cwd);
  if (untrusted) throw new GitError(`refusing to run Git in ${cwd}: it is not a trusted worktree of this repository (${untrusted})`, null, args);
  const result = spawnSync("git", [...PINNED_GIT_FLAGS, ...args], {
    cwd,
    encoding: "utf8",
    stdio: ["pipe", "pipe", "pipe"],
    input: options.input ?? "",
    env: { ...baseEnv(), ...(options.env ?? {}) },
    timeout: options.timeoutMs ?? 30_000,
    maxBuffer: options.maxBuffer ?? 32 * 1024 * 1024,
  });
  const timedOut = (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT";
  const out: GitResult = { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "", timedOut };
  if (result.error && !timedOut) throw new GitError(`git could not run: ${(result.error as Error).message}`, null, args);
  if (!options.allowFailure && (timedOut || result.status !== 0)) {
    const detail = timedOut ? "timed out" : redactSecrets(out.stderr.trim().split("\n")[0] ?? "").slice(0, 300);
    throw new GitError(`git ${args[0] ?? ""} failed: ${detail || `exit ${result.status}`}`, result.status, args);
  }
  return out;
}

/** `git ...` stdout, trimmed of one trailing newline. */
export function gitOut(cwd: string, args: readonly string[], options: GitOptions = {}): string {
  return git(cwd, args, options).stdout.replace(/\n$/, "");
}
