/**
 * A pathspec-mode variable inherited from the operator's shell (GIT_LITERAL_PATHSPECS=1, set by some tools) turns the
 * `:(top).nexus` magic pathspec into a literal file name, so the exclusion of Nexus's internal state silently stops
 * working. The worktree Git helper computes its environment once per process, so this file sets the variable BEFORE
 * the first Git call in the process (dynamic import below) and runs in its own process.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";

process.env.GIT_LITERAL_PATHSPECS = "1";
const { runWorktreeCommand } = await import("../src/worktrunk/command.js");
const { SCRUBBED_ENV } = await import("../src/worktrunk/git.js");
const { PATHSPEC_MODE_ENV } = await import("../src/git.js");

function git(cwd: string, ...args: string[]): string {
  const env = { ...process.env };
  delete env.GIT_LITERAL_PATHSPECS;
  return execFileSync("git", args, { cwd, env, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

test("an inherited GIT_LITERAL_PATHSPECS=1 does not make the .nexus exclusion literal: tracked state is neither backed up nor committed", () => {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-wtenv-")));
  try {
    const repo = path.join(root, "proj");
    const home = path.join(root, "home");
    fs.mkdirSync(repo);
    fs.mkdirSync(home);
    git(repo, "init", "-q", "-b", "main");
    git(repo, "config", "user.email", "t@example.com");
    git(repo, "config", "user.name", "T");
    git(repo, "config", "commit.gpgsign", "false");
    fs.writeFileSync(path.join(repo, "a.txt"), "one\n");
    git(repo, "add", ".");
    git(repo, "commit", "-q", "-m", "init");
    const dir = path.join(repo, ".nexus", "worktrees", "feat-env");
    fs.appendFileSync(path.join(repo, ".git", "info", "exclude"), ".nexus/\n");
    git(repo, "worktree", "add", "-q", "-b", "feat/env", dir); // plain Git: this test is about the merge, not worktree creation
    fs.mkdirSync(path.join(dir, ".nexus"), { recursive: true });
    fs.writeFileSync(path.join(dir, ".nexus", "knowledge.json"), '{"v":1}\n');
    git(dir, "add", "-f", ".nexus/knowledge.json");
    git(dir, "commit", "-q", "-m", "an old commit that tracked internal state");
    fs.writeFileSync(path.join(dir, ".nexus", "knowledge.json"), '{"v":2,"edited by a session":true}\n');
    fs.writeFileSync(path.join(dir, "real.txt"), "real work\n");
    const merged = runWorktreeCommand(["merge", "--no-verify-receipt", "--reason", "pathspec env fixture"], { cwd: dir, home, readOnly: false });
    assert.equal(merged.success, true, merged.output);
    assert.equal(git(repo, "show", "main:real.txt"), "real work");
    assert.equal(git(repo, "show", "main:.nexus/knowledge.json"), '{"v":1}', "the state edit was committed under an inherited literal-pathspec mode");
  } finally { fs.rmSync(root, { recursive: true, force: true }); }
});

test("the worktree Git helper scrubs every pathspec-mode variable the /commit helper does", () => {
  assert.deepEqual([...PATHSPEC_MODE_ENV].sort(), ["GIT_GLOB_PATHSPECS", "GIT_ICASE_PATHSPECS", "GIT_LITERAL_PATHSPECS", "GIT_NOGLOB_PATHSPECS"]);
  for (const name of PATHSPEC_MODE_ENV) assert.ok(SCRUBBED_ENV.includes(name), `${name} is scrubbed`);
});
  test("hasChangesAt resolves the branch as a branch, not a same-named tag", () => {
    const f = fixture();
    try {
      fs.writeFileSync(path.join(f.dir, "b.txt"), "two\n");
      git(f.dir, "add", "b.txt");
      git(f.dir, "-c", "user.email=t@example.com", "-c", "user.name=T", "-c", "commit.gpgsign=false", "commit", "-q", "-m", "work");
      git(f.repo, "tag", "feat/bind", "HEAD");
      const manager = new WorktreeManager(f.repo);
      assert.equal(manager.hasChangesAt(f.dir, "feat/bind"), true, "a tag at main's HEAD must not hide the branch's commits");
    } finally { f.cleanup(); }
  });

  test("ensureNamedWorktree refuses the primary checkout's branch and returns only a registered linked worktree", () => {
    const f = fixture();
    try {
      const manager = new WorktreeManager(f.repo);
      assert.throws(() => manager.ensureNamedWorktree("main", f.home), /primary checkout/);
      assert.equal(fs.existsSync(path.join(f.repo, ".nexus", "worktrees", "main")), false, "nothing was created for it");
      const reused = manager.ensureNamedWorktree("feat/bind", f.home);
      assert.deepEqual(reused, { branch: "feat/bind", path: f.dir, created: false });
      const made = manager.ensureNamedWorktree("feat/new", f.home);
      assert.equal(made.created, true);
      assert.equal(isNamedWorktreePath(WorkspacePath.fromSelectedWorkspace(f.repo), made.path, { ...namedBinding(f), branch: "feat/new" }), true);
    } finally { f.cleanup(); }
  });

  test("a redirected .git pointer is refused before any host-side Git runs, and its fsmonitor never executes", () => {
    const f = fixture();
    try {
      const manager = new WorktreeManager(f.repo);
      const root = WorkspacePath.fromSelectedWorkspace(f.repo);
      assert.equal(manager.isLinkedWorktree(f.dir), true);
      assert.equal(isNamedWorktreePath(root, f.dir, namedBinding(f)), true);
      // What a sandboxed agent can do: make `.git` point at a repository it controls, whose config runs a command.
      const marker = path.join(f.root, "fsmonitor-ran");
      const script = path.join(f.root, "fsmonitor.sh");
      fs.writeFileSync(script, `#!/bin/sh\ntouch '${marker}'\nexit 0\n`, { mode: 0o755 });
      const planted = path.join(f.dir, "x");
      git(f.dir, "init", "-q", planted);
      git(planted, "config", "core.fsmonitor", script);
      fs.writeFileSync(path.join(f.dir, ".git"), "gitdir: ./x/.git\n");
      assert.equal(manager.isLinkedWorktree(f.dir), false);
      assert.equal(isNamedWorktreePath(root, f.dir, namedBinding(f)), false, "the validator fails closed");
      assert.equal(manager.hasChangesAt(f.dir, "feat/bind"), true, "fail closed: not safe to treat as clean");
      assert.equal(fs.existsSync(marker), false, "host-side git status executed the planted fsmonitor command");
    } finally { f.cleanup(); }
  });
});

